def analyze_sales_data(df):
    """
    Analyzes sales data, providing insights into orders, products, customers,
    and time trends.  Includes top/bottom 5 analysis.

    Args:
        df (pd.DataFrame): DataFrame with sales data.
    """

    # 1. Data Loading and Inspection (Modified to handle potential errors and be more robust)
    print("\n--- 1. Data Loading and Inspection ---")
    print(df.head())
    print(df.info())

    # Check for missing values in key columns.
    missing_values = df[['ORDERNUMBER', 'QUANTITYORDERED', 'PRICEEACH', 'SALES', 'ORDERDATE', 'STATUS', 'PRODUCTLINE', 'CUSTOMERNAME', 'CITY', 'COUNTRY']].isnull().sum()
    print("\nMissing Values:")
    print(missing_values[missing_values > 0].to_markdown(numalign="left", stralign="left"))

    # Check for duplicate order numbers
    duplicate_orders = df['ORDERNUMBER'].duplicated().sum()
    print(f"\nNumber of duplicate order numbers: {duplicate_orders}")

    # 2. Temporal Analysis
    print("\n--- 2. Temporal Analysis ---")
    df['ORDERDATE'] = pd.to_datetime(df['ORDERDATE'])
    df['DAY'] = df['ORDERDATE'].dt.day
    df['WEEK'] = df['ORDERDATE'].dt.isocalendar().week
    df['MONTH'] = df['ORDERDATE'].dt.month
    df['YEAR'] = df['ORDERDATE'].dt.year
    df['DAY_OF_WEEK'] = df['ORDERDATE'].dt.day_name()  # Get day names

    def show_top_bottom(df, column, title):
        """Helper function to display top and bottom 5 values."""
        top_5 = df.groupby(column)['SALES'].sum().nlargest(5).reset_index()
        bottom_5 = df.groupby(column)['SALES'].sum().nsmallest(5).reset_index()
        print(f"\n{title} - Top 5:")
        print(top_5.to_markdown(index=False, numalign="left", stralign="left"))
        print(f"\n{title} - Bottom 5:")
        print(bottom_5.to_markdown(index=False, numalign="left", stralign="left"))

    show_top_bottom(df, 'ORDERDATE', 'Sales by Date')
    show_top_bottom(df, 'MONTH', 'Sales by Month')
    show_top_bottom(df, 'YEAR', 'Sales by Year')
    show_top_bottom(df, 'DAY_OF_WEEK', 'Sales by Day of Week') # Use the day names

    # 3. Product Analysis
    print("\n--- 3. Product Analysis ---")
    show_top_bottom(df, 'PRODUCTLINE', 'Sales by Product Line')
    show_top_bottom(df, 'PRODUCTCODE', 'Sales by Product Code')

    df['DISCOUNT'] = df['MSRP'] - df['PRICEEACH']
    avg_discount_by_product = df.groupby('PRODUCTCODE')['DISCOUNT'].mean().reset_index()
    print("\nAverage Discount by Product Code:\n", avg_discount_by_product.head().to_markdown(index=False, numalign="left", stralign="left"))

    plt.figure(figsize=(8, 6))
    sns.scatterplot(x='QUANTITYORDERED', y='SALES', data=df, alpha=0.5)
    plt.title('Quantity Ordered vs. Sales')
    plt.xlabel('Quantity Ordered')
    plt.ylabel('Sales')
    plt.show()

    # 4. Customer Analysis
    print("\n--- 4. Customer Analysis ---")
    show_top_bottom(df, 'CUSTOMERNAME', 'Sales by Customer')
    show_top_bottom(df, 'CITY', 'Sales by City')
    show_top_bottom(df, 'COUNTRY', 'Sales by Country')

    deal_size_counts = df['DEALSIZE'].value_counts().reset_index()
    deal_size_counts = deal_size_counts.rename(columns={'index': 'DEALSIZE', 'DEALSIZE': 'COUNT'})
    print("\nDeal Size Distribution:\n", deal_size_counts.to_markdown(index=False, numalign="left", stralign="left"))

    plt.figure(figsize=(8, 6))
    sns.countplot(x='DEALSIZE', data=df)
    plt.title('Distribution of Deal Sizes')
    plt.xlabel('Deal Size')
    plt.ylabel('Count')
    plt.show()

    # 5. Order Analysis
    print("\n--- 5. Order Analysis ---")
    status_counts = df['STATUS'].value_counts().reset_index()
    status_counts = status_counts.rename(columns={'index': 'STATUS', 'STATUS': 'COUNT'})
    print("\nOrder Status Distribution:\n", status_counts.to_markdown(index=False, numalign="left", stralign="left"))

    plt.figure(figsize=(8, 6))
    sns.countplot(x='STATUS', data=df)
    plt.title('Distribution of Order Statuses')
    plt.xlabel('Order Status')
    plt.ylabel('Count')
    plt.show()

    # 6. Additional Analysis - Sales by Customer and Product
    print("\n--- 6. Sales by Customer and Product ---")
    customer_product_sales = df.groupby(['CUSTOMERNAME', 'PRODUCTLINE'])['SALES'].sum().reset_index()
    top_customers_products = customer_product_sales.nlargest(5, 'SALES')
    print("Top 5 Customers and Products by Sales:\n", top_customers_products.to_markdown(index=False, numalign="left", stralign="left"))

    bottom_customers_products = customer_product_sales.nsmallest(5, 'SALES')
    print("Bottom 5 Customers and Products by Sales:\n", bottom_customers_products.to_markdown(index=False, numalign="left", stralign="left"))

analyze_sales_data(df)

