from statsmodels.tsa.stattools import adfuller
from statsmodels.graphics.tsaplots import plot_acf, plot_pacf

# Aggregate sales by year and month
monthly_sales = df.groupby(['YEAR_ID', 'MONTH_ID'])['SALES'].sum().reset_index()

# Create a combined year-month column for easier time series indexing
monthly_sales['time_index'] = pd.to_datetime(monthly_sales['YEAR_ID'].astype(str) + '-' + monthly_sales['MONTH_ID'].astype(str), format='%Y-%m')

# **Ensure time_index is the index and is a DatetimeIndex**
monthly_sales = monthly_sales.set_index('time_index')
monthly_sales = monthly_sales.sort_index()  # Sort the index
monthly_sales = monthly_sales[['SALES']]

print(monthly_sales.head())
print(monthly_sales.info()) #check the index type.

# Explore Your Data (EDA):
# Visualize: Plot monthly_sales over time. Look for trends, seasonality, and any significant events or patterns.
plt.figure(figsize=(12, 6))
sns.lineplot(data=monthly_sales, x=monthly_sales.index, y='SALES')
plt.title('Total Monthly Sales Over Time')
plt.xlabel('Date')
plt.ylabel('Total Sales')
plt.show()

# Statistical Analysis:
# Calculate descriptive statistics of monthly_sales.
print(monthly_sales.describe())

# Check for stationarity using tests like the Augmented Dickey-Fuller (ADF) test (if needed for ARIMA).
result = adfuller(monthly_sales['SALES'])
print('\nADF Statistic:', result[0])
print('p-value:', result[1])
print('Critical Values:', result[4])

# Analyze autocorrelation and partial autocorrelation functions (ACF and PACF) to identify potential ARIMA model orders (if considering ARIMA).
plot_acf(monthly_sales['SALES'], lags=min(30, len(monthly_sales) - 1))  # Limit lags
plt.title('Autocorrelation Function (ACF)')
plt.show()
plot_pacf(monthly_sales['SALES'], lags=min(30, len(monthly_sales) // 2 -1 )) # Limit lags.  Integer division
plt.title('Partial Autocorrelation Function (PACF)')
plt.show()

"""Total Monthly Sales Over Time:

Trend: There doesn't appear to be a strong, consistent upward or downward trend across the entire period. Sales fluctuate.
Seasonality: There are clear peaks in sales around the end of each year (notice the spikes in late 2003 and late 2004). This strongly suggests annual seasonality, likely driven by holiday shopping.
Outliers: The peaks are quite pronounced, indicating significant increases in sales during those periods.
Length of Series: The data spans from early 2003 to early 2005, which is a relatively short time series (approximately 2 years and a few months). This might limit the effectiveness of some more complex models that require longer historical data.

3. monthly_sales.describe():

Provides basic statistics about the monthly sales. The standard deviation is quite high relative to the mean, indicating significant variability in monthly sales. The large difference between the 75th percentile and the maximum further highlights the impact of the peak sales months.
4. ADF Test :

ADF Statistic: -3.629
p-value: 0.005
Critical Values: 1%:-3.689, 5%:-2.972, 10%:-2.625
Interpretation: The p-value (0.005) is less than the common significance levels (0.05 and 0.01). The ADF statistic (-3.629) is also more negative than the critical values at the 5% and 1% levels (though slightly less negative than the 1% critical value). This suggests that we can reject the null hypothesis of non-stationarity. Therefore, the monthly sales data is likely stationary or close to stationary. This is good news for using models like ARIMA/SARIMA, as they often require stationary data.
5. Autocorrelation Function (ACF) :

There's a significant spike at lag 1, indicating a strong correlation between sales in one month and the sales in the immediately preceding month.
There are also noticeable spikes at lags around 12, suggesting a correlation with sales from the same month in the previous year (annual seasonality). The decaying pattern of the ACF further supports the presence of autocorrelation.
6. Partial Autocorrelation Function (PACF):

The significant spikes at lags 1, 2, and possibly a few others initially suggest that a few autoregressive (AR) terms might be important if we were to use an ARIMA model. The PACF helps to isolate the direct effect of a past lag on the current observation, removing the influence of the intermediate lags.
Next Step: Selecting Candidate Models (Refined)

**Summary 4:**
**Potential Forecasting Methods (For Total Monthly Sales)**

Given the insights from the EDA and stationarity test, let's refine our candidate models for forecasting total monthly sales:

**Prophet**: Remains a strong contender due to its ability to handle seasonality and potential trend changes, and it's often robust with shorter time series.

**SARIMA** (Seasonal ARIMA): The ACF and PACF plots, along with the stationary nature of the data and the clear annual seasonality (lag 12 in ACF), make SARIMA a viable option. We'll need to determine the appropriate (p, d, q) and (P, D, Q, s) orders based on the ACF and PACF.

**Holt-Winters Exponential Smoothing:** Still a good choice for capturing trend (although it's weak here) and the strong seasonality. We'll need to consider both additive and multiplicative seasonality.

**Step:5 Model Implementation, Model Evaluation and Visualization**

let's split our monthly_sales DataFrame into training and testing sets. A common approach for time series data is to use a chronological split. Since our data goes up to 2005, let's use data up to the end of 2004 for training and the data in 2005 for testing.
"""

# Determine the split point (end of 2004)
train_data = monthly_sales[monthly_sales.index < '2005-01-01']
test_data = monthly_sales[monthly_sales.index >= '2005-01-01']

print("Training data shape:", train_data.shape)
print("Testing data shape:", test_data.shape)

# Visualize the split
plt.figure(figsize=(12, 6))
plt.plot(train_data.index, train_data['SALES'], label='Training Data')
plt.plot(test_data.index, test_data['SALES'], label='Testing Data', color='orange')
plt.title('Training and Testing Data Split')
plt.xlabel('Date')
plt.ylabel('Total Sales')
plt.legend()
plt.show()

"""The plot clearly shows the training data (blue line) leading up to the test data (orange line). The seasonal peaks at the end of each year are evident in the training data. The test data shows the beginning of 2005 and the subsequent months.
Next Step: Train and Evaluate Prophet

Now that we have our training and testing sets, let's proceed with training the Prophet model.

**I. prophet**
"""

from prophet import Prophet
import numpy as np
from sklearn.metrics import mean_absolute_error, mean_squared_error, mean_absolute_percentage_error

# Prepare the training data for Prophet
prophet_train_data = train_data.reset_index()
prophet_train_data = prophet_train_data.rename(columns={'time_index': 'ds', 'SALES': 'y'})

# Initialize and fit the Prophet model
model = Prophet()
model.fit(prophet_train_data)

# Create future dataframe for predictions
future = pd.date_range(start=test_data.index.min(), end=test_data.index.max(), freq='MS') # 'MS' for month start
future = pd.DataFrame({'ds': future})

# Make predictions
forecast = model.predict(future)

# Evaluate the model
predictions = forecast['yhat'].values
actuals = test_data['SALES'].values

mae = mean_absolute_error(actuals, predictions)
rmse = np.sqrt(mean_squared_error(actuals, predictions))
mape = mean_absolute_percentage_error(actuals, predictions) * 100

print(f'Prophet Mean Absolute Error (MAE): {mae:.2f}')
print(f'Prophet Root Mean Squared Error (RMSE): {rmse:.2f}')
print(f'Prophet Mean Absolute Percentage Error (MAPE): {mape:.2f}%')

# Visualize the forecast
plt.figure(figsize=(12, 6))
plt.plot(train_data.index, train_data['SALES'], label='Training Data')
plt.plot(test_data.index, test_data['SALES'], label='Actual Sales (Test)')
plt.plot(future['ds'], forecast['yhat'], label='Prophet Forecast', color='red')
plt.fill_between(future['ds'], forecast['yhat_lower'], forecast['yhat_upper'], color='red', alpha=0.2)
plt.title('Prophet Forecast vs. Actual Sales')
plt.xlabel('Date')
plt.ylabel('Total Sales')
plt.legend()
plt.show()

"""Mean Absolute Error (MAE): 226275.53: On average, the Prophet model's predictions are off by approximately $226,275.53.
Root Mean Squared Error (RMSE): 234077.38: The RMSE is slightly higher than the MAE, which indicates that there are some larger errors in the predictions (RMSE penalizes larger errors more).
Mean Absolute Percentage Error (MAPE): 68.37%: This is a high MAPE value. It suggests that, on average, the absolute percentage difference between the forecasted sales and the actual sales in the test set is about 68.37%. This indicates a significant level of inaccuracy in the Prophet model's forecast for this dataset.
Insights from the Forecast Plot:

The blue line represents the training data, showing the historical monthly sales with the characteristic year-end peaks.
The orange line represents the actual sales in the test set (the months of 2005).
The red line represents the Prophet forecast.
The shaded pink area represents the uncertainty intervals around the forecast.
Visually, the Prophet forecast seems to capture a slight upward trend in 2005 but significantly underestimates the actual sales in the test period. The wide uncertainty intervals also reflect the model's difficulty in making accurate predictions for this period. The model doesn't seem to have accurately captured the magnitude of the sales in the initial months of 2005.

**Summary I:**Given the high MAPE and the visual discrepancy between the forecast and the actual sales in the test set, the Prophet model, in its default configuration, doesn't appear to be providing a satisfactory forecast for this data.

Let's move on to Holt-Winters Exponential Smoothing. We'll try both additive and multiplicative seasonality to see which fits the data better.
"""



"""**II. Holt-Winters Exponential Smoothing**"""

from statsmodels.tsa.holtwinters import ExponentialSmoothing, SimpleExpSmoothing, Holt

# Fit Holt-Winters Additive Seasonality Model
hw_add = ExponentialSmoothing(train_data['SALES'],
                            seasonal_periods=12,
                            trend='add',
                            seasonal='add',
                            initialization_method="estimated").fit()
hw_add_predictions = hw_add.forecast(len(test_data))

# Fit Holt-Winters Multiplicative Seasonality Model
hw_mul = ExponentialSmoothing(train_data['SALES'],
                            seasonal_periods=12,
                            trend='add',
                            seasonal='mul',
                            initialization_method="estimated").fit()
hw_mul_predictions = hw_mul.forecast(len(test_data))

# Evaluate Holt-Winters Additive Model
mae_add = mean_absolute_error(test_data['SALES'], hw_add_predictions)
rmse_add = np.sqrt(mean_squared_error(test_data['SALES'], hw_add_predictions))
mape_add = mean_absolute_percentage_error(test_data['SALES'], hw_add_predictions) * 100

print("\nHolt-Winters Additive Seasonality:")
print(f'MAE: {mae_add:.2f}')
print(f'RMSE: {rmse_add:.2f}')
print(f'MAPE: {mape_add:.2f}%')

# Evaluate Holt-Winters Multiplicative Model
mae_mul = mean_absolute_error(test_data['SALES'], hw_mul_predictions)
rmse_mul = np.sqrt(mean_squared_error(test_data['SALES'], hw_mul_predictions))
mape_mul = mean_absolute_percentage_error(test_data['SALES'], hw_mul_predictions) * 100

print("\nHolt-Winters Multiplicative Seasonality:")
print(f'MAE: {mae_mul:.2f}')
print(f'RMSE: {rmse_mul:.2f}')
print(f'MAPE: {mape_mul:.2f}%')

# Visualize Holt-Winters Forecasts
plt.figure(figsize=(12, 6))
plt.plot(train_data.index, train_data['SALES'], label='Training Data')
plt.plot(test_data.index, test_data['SALES'], label='Actual Sales (Test)')
plt.plot(test_data.index, hw_add_predictions, label='Holt-Winters Additive Forecast', color='green')
plt.plot(test_data.index, hw_mul_predictions, label='Holt-Winters Multiplicative Forecast', color='purple')
plt.title('Holt-Winters Forecasts vs. Actual Sales')
plt.xlabel('Date')
plt.ylabel('Total Sales')
plt.legend()
plt.show()

"""Comparison with Prophet:

The Holt-Winters models, especially the additive version (MAPE of 17.01%), have significantly outperformed the Prophet model (MAPE of 68.37%) on this dataset based on the evaluation metrics. The MAE and RMSE are also considerably lower for Holt-Winters.
Insights from the Forecast Plot:

The green line (Holt-Winters Additive) and the purple line (Holt-Winters Multiplicative) both appear to follow the general trend of the actual sales (orange line) in the test set much better than the Prophet forecast did.
The Holt-Winters Additive forecast seems to be slightly closer to the actual values visually in the later part of the test set.
Both Holt-Winters models capture a degree of the level change observed in the test data, which Prophet missed.

**Summary II:** Given that the Holt-Winters models have shown much better performance than Prophet, our next steps should focus on refining the Holt-Winters approach.
Based on the lower MAPE, MAE, and RMSE, the Holt-Winters Additive Seasonality model appears to be the better performer between the two. We can proceed with this model as our current best.
"""

import itertools
from sklearn.model_selection import ParameterGrid

# Define the range of parameters to search
param_grid = {
    'smoothing_level': np.linspace(0.1, 0.9, 5),
    'smoothing_trend': np.linspace(0.1, 0.5, 3),
    'smoothing_seasonal': np.linspace(0.1, 0.9, 5)
}

grid = ParameterGrid(param_grid)
best_mape = float('inf')
best_params = {}

for params in grid:
    try:
        model = ExponentialSmoothing(train_data['SALES'],
                                     seasonal_periods=12,
                                     trend='add',
                                     seasonal='add',
                                     initialization_method="estimated")
        fit_model = model.fit(**params)
        predictions = fit_model.forecast(len(test_data))
        mape = mean_absolute_percentage_error(test_data['SALES'], predictions) * 100
        if mape < best_mape:
            best_mape = mape
            best_params = params
    except ValueError:
        continue # Some parameter combinations might not work

print("\nBest Holt-Winters Additive Parameters:", best_params)
print("Best Holt-Winters Additive MAPE:", best_mape)

# Train the best model and visualize the forecast
best_hw_add = ExponentialSmoothing(train_data['SALES'],
                                  seasonal_periods=12,
                                  trend='add',
                                  seasonal='add',
                                  initialization_method="estimated").fit(**best_params)
best_hw_add_predictions = best_hw_add.forecast(len(test_data))

plt.figure(figsize=(12, 6))
plt.plot(train_data.index, train_data['SALES'], label='Training Data')
plt.plot(test_data.index, test_data['SALES'], label='Actual Sales (Test)')
plt.plot(test_data.index, best_hw_add_predictions, label='Best Holt-Winters Additive Forecast', color='red')
plt.title('Best Holt-Winters Additive Forecast vs. Actual Sales')
plt.xlabel('Date')
plt.ylabel('Total Sales')
plt.legend()
plt.show()

